From f5cf540d93fad86e1e3f761bd065be28b614f38b Mon Sep 17 00:00:00 2001
From: Gregory Petrosyan <gregory.petrosyan@gmail.com>
Date: Thu, 3 Apr 2014 14:24:08 +0400
Subject: [PATCH] jack: fix underrun handling issue introduced in ed5234bbc


diff --git a/jack.c b/jack.c
index 2c55184..f30c328 100644
--- a/jack.c
+++ b/jack.c
@@ -131,6 +131,7 @@ static int op_jack_cb(jack_nframes_t frames, void* arg)

 	if (underrun) {
 		/* if there is an underrun channels may be out of sync. */
+		underrun = 0;
 		for (int i = 0; i < CHANNELS; i++) {
 			int pos_diff = buffer_pos_max - buffer_pos[i];
 			if (pos_diff <= 0) {
@@ -148,7 +149,6 @@ static int op_jack_cb(jack_nframes_t frames, void* arg)
 				underrun = 1;
 			}
 		}
-		underrun = 0;
 	}

 	if (paused) {
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the premature resetting of the `underrun` variable at the end of the underrun handling block, which could lead to incorrect synchronization of audio channels when an underrun occurred. This change disrupted the logic that checks and processes the state of each channel, potentially allowing the system to misinterpret the underrun condition.

        Commit message:
        jack: fix underrun handling issue introduced in ed5234bbc  

        Patch:

 static int op_jack_cb(jack_nframes_t frames, void* arg)
 {
 	size_t bytes_want = frames * sizeof(jack_default_audio_sample_t);

 	if (underrun) {
 		/* if there is an underrun channels may be out of sync. */
+		underrun = 0;
 		for (int i = 0; i < CHANNELS; i++) {
 			int pos_diff = buffer_pos_max - buffer_pos[i];
 			if (pos_diff <= 0) {
 				continue;
 			}

 			/* trash pos_diff bytes */
 			char trash[frames * sizeof(jack_default_audio_sample_t)];
 			size_t bytes_read = jack_ringbuffer_read(ringbuffer[i], (char*) trash, pos_diff);

 			buffer_pos[i] += bytes_read;
 			if (buffer_pos_max > buffer_pos[i]) {
 				/* still not synced */
 				d_print("channel %d still out of sync", i);
 				underrun = 1;
 			}
 		}
-		underrun = 0;
 	}

 	if (paused) {
 		for (int i = 0; i < CHANNELS; i++) {
 			jack_default_audio_sample_t* jack_buf = jack_port_get_buffer(output_ports[i], frames);
 			memset((char*) jack_buf, 0, bytes_want);
 		}
 		return 0;
 	}

 	for (int i = 0; i < CHANNELS; i++) {
 		jack_default_audio_sample_t* jack_buf = jack_port_get_buffer(output_ports[i], frames);
 		size_t bytes_read = jack_ringbuffer_read(ringbuffer[i], (char*) jack_buf, bytes_want);

 		buffer_pos[i] += bytes_read;
 		if (bytes_read > buffer_pos_max) {
 			buffer_pos_max = bytes_read;
 		}

 		if (bytes_read < bytes_want) {
 			underrun = 1;

 			size_t fill_length = bytes_want - bytes_read;
 			char* fill_offset = ((char*) jack_buf) + bytes_read;
 			memset(fill_offset, 0, fill_length);
 		}
 	}

 	return 0;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
